create table enfrentamientos

(
    id          int auto_increment
        primary key,
    id_unidad_1 varchar(45)                   null,
    id_unidad_2 varchar(45)                   null,
    alias_1     varchar(45)                   null,
    alias_2     varchar(45)                   null,
    valor       int                           null,
    resultado   varchar(45) default 'Derrota' null
);

